-- 0118：師妹第一章「先敬神明」（蜜糖版，2026-11-14 六六定稿）
--
-- 線上原本沒有師妹的角色事件，新增。改寫自 ai-studio pending 1103-145000-eeab 的「先敬神明」一線（第 5、6 輪），
-- 拿掉混進來的失物／木牌／井欄支線；大師兄只被提到、不出場。
-- 獎勵只有靈石 10＋她的身分「糖大小姐」（玩家稱號不發，同 0116 觀貓第一章）。
-- 身分由 0065 的 trigger 自動建 character_titles 一列，這裡補聲口與說明。
-- 道緣成就「甘節」在 _shared/achievements.ts（dy_daoshi_f），不在資料庫。
-- 前端道緣事件目前全部關著（STORY_OPEN_CIDS 清空），上架不會馬上被玩到。

insert into character_events (id, character_id, chapter, seq, title, summary, require_favor, require_cultivation, require_event,
  scenes, choices, rewards, reward_lingshi, reward_avatar, reward_title, reward_memory, published)
values ('daoshi_f_c1', 'daoshi_f', 1, 1, '先敬神明', '幾知觀不收禮。神明收。', 0, 0, null,
  $sc$[{"bg":"qianting","place":"前廳・申時","text":"申時，幾知觀前廳。茶剛換過一輪，爐上的水還沒滾。\n你頭一回登門，不好空手，捧著一只繫了紅繩的木匣。"},{"portrait":"daoshi_f","who":"daoshi_f","text":"「施主有心了。」\n她雙手接住木匣，沒有收下，原樣推回你面前，連紅繩的結都沒碰歪。\n「只是幾知觀不收外客之禮，還請帶回。」"},{"me":true,"text":"「不是什麼貴重東西。道長看一眼再推，也不遲。」\n（我解開紅繩，掀起匣蓋。）"},{"who":"daoshi_f","text":"匣裡是一格一格的蜜漬金桔，糖衣透亮，還帶著一點桂花香。\n她的目光在匣裡停了一停。推匣的那隻手沒有收回去，也沒有再往前推。\n「道長二字不敢當，我只是觀裡的二弟子。」"},{"who":"daoshi_f","text":"她指尖輕抵唇邊，像是在替你想辦法。\n「規矩是不收外客之禮。不過——若是拿去敬拜神明，那便另當別論。」\n「神明收的是香火，不算觀裡收的。」","choices":[{"key":"c1","label":"「那就勞煩代我供上。」","hint":"順著臺階下","to":"a1"},{"key":"c2","label":"「這條規矩，是剛想出來的吧？」","hint":"當面戳破","to":"b1"}]},{"id":"a1","who":"daoshi_f","text":"「施主明白事理。」\n她這回把木匣接穩了，接得比方才推回來時快上許多。\n「請隨我到大殿。供果要趁糖衣還亮的時候上。」","next":"s2"},{"id":"b1","who":"daoshi_f","text":"她笑意不減，連眼睫都沒多動一下。\n「施主說笑了。規矩是觀主立的，我只是記得比旁人熟些。」\n她順手把匣蓋合上，抱進了懷裡。\n「大殿這邊請。再站下去，糖衣要讓茶氣燻潮了。」"},{"id":"s2","bg":"dadian","place":"大殿・一炷香","text":"大殿裡只點著長明燈。\n她先淨了手，取一只白瓷盤，把金桔一顆一顆疊成塔，最亮的那顆放在頂上。\n疊完退後一步端詳，又上前把歪了的一顆扶正。"},{"who":"daoshi_f","text":"她點了香，舉過眉心，端端正正拜了三拜，沒有一拜是草率的。\n香插進爐裡，她才回頭，聲音壓得很低。\n「拜是真心拜的。要等這一炷香燒完，才算神明享過，早一刻都不行。」"},{"me":true,"text":"「那……燒完之後呢？」"},{"who":"daoshi_f","text":"「燒完之後，供果就不是禮了。」\n她在蒲團旁站定，眼睛看著香頭，沒看那盤金桔。\n「施主稍坐。香走得慢，急不得。」"},{"text":"香灰落了三回。\n她始終沒有動，只在最後一截香燒到底時，往前挪了半步。\n青煙一斷，白瓷盤已經端在她手上。"},{"id":"s3","bg":"langxia","place":"廊下・日影斜","text":"廊下日影斜長。欄杆上蹲著一隻胖碩的棕色虎斑貓，披著黑色雲紋短披風，頸上的銅牌刻著一個「知」字。\n牠瞇著眼，看的不是人，是盤子。"},{"who":"daoshi_f","text":"「這位是觀裡的吉祥物，施主喚牠喵大人就好。」\n她在石階上坐下，把一顆金桔掰成兩半，一半放到貓的面前。\n「拜過了，剩下的是福分。」"},{"portrait":"lingshou","who":"lingshou","text":"牠低頭嗅了嗅，用爪子把那半顆撥到一邊。\n「小的。」\n牠的尾巴在欄杆上敲了一下。\n「小姑娘，打發香客才用半顆。」"},{"me":true,"text":"（一隻貓開口挑嘴——我愣了一下，沒敢出聲。）"},{"portrait":"daoshi_f","who":"daoshi_f","text":"她不慌不忙，換了一整顆放過去，掰下來的那一半順手進了自己嘴裡。\n「喵大人教訓得是。放著不吃，才是糟蹋神明心意。」\n她抬眼看你，唇角還帶著一點糖光。\n「施主也是香客，這福分有施主一份。」","choices":[{"key":"c3","label":"「那我就不客氣了。」","hint":"領一份福分","to":"a2"},{"key":"c4","label":"「原來供品是這樣分的。」","hint":"打趣她","to":"b2"}]},{"id":"a2","who":"daoshi_f","text":"她挑了一顆糖衣最厚的，連盤子一起遞到你手邊，自己的手先退了回去。\n「施主送的東西，自己還沒嚐過吧。」\n「好東西要有人一起吃，才記得住味道。」","next":"s4"},{"id":"b2","who":"daoshi_f","text":"「施主看得真仔細。」\n她笑著又掰開一顆，這回兩半都放到了貓的面前。\n「香是真心上的，果子也是真心吃的。兩樣都不摻假，神明不會見怪。」\n她把盤子往你這邊推了一寸。"},{"id":"s4","portrait":"lingshou","who":"lingshou","text":"牠吃完一整顆，舔了舔嘴邊的白毛，鼻尖忽然朝灶房的方向動了動。\n「小姑娘。妳灶上還坐著東西。」"},{"portrait":"daoshi_f","who":"daoshi_f","text":"她掰金桔的手停住了。\n「……山楂。」\n她起身的動作依舊端莊，步子卻比來時快了一倍。"},{"id":"s5","bg":"zaofang","place":"灶房・焦糖氣","text":"灶房裡的甜味濃得發沉，尾巴上拖著一點焦。\n砂鍋裡的糖漬山楂咕嘟作響，顏色紅得近黑。案上一只冰糖罐敞著口，已經見底。"},{"who":"daoshi_f","text":"她墊著布把砂鍋端離了火，拿木勺攪了兩下，糖漿拉出長長的絲。\n「原想熬一罐，留著給觀裡配茶的。」\n她舀起一顆吹涼，自己先嚐，眉心輕輕一動。"},{"portrait":"lingshou","who":"lingshou","text":"牠跳上灶邊的條凳，探頭聞了一下，立刻把臉轉開。\n「甜到發苦。不如那小子做的。」\n牠的尾巴掃過那只空罐。\n「那小子一錢糖秤三回。妳倒好，一罐冰糖，一鍋倒完——好個糖大小姐。」"},{"portrait":"daoshi_f","who":"daoshi_f","text":"她笑出了聲，沒有辯解半句。\n「喵大人說得是。師兄照方子一錢一秤，我是覺得不夠，順手就多添了。」\n她另取一只小碟，盛了一顆遞給你。\n「施主替我評評理。是苦，還是只是甜得久了些？」","choices":[{"key":"c5","label":"「甜過頭了，回口是苦的。」","hint":"照實說","to":"a3"},{"key":"c6","label":"「配一壺濃茶，剛好。」","hint":"替她鋪個臺階","to":"b3"}]},{"id":"a3","who":"daoshi_f","text":"「施主舌頭直。」\n她點點頭，把自己碟裡剩的那半顆也吃了，吃得很慢。\n「客氣話我聽得多，這一句倒新鮮。火候過了就是過了，我認。」","next":"s6"},{"id":"b3","who":"daoshi_f","text":"她偏頭想了想，眼裡的笑意深了一層。\n「濃茶壓甜，山楂解膩。施主這是替我把一鍋熬壞的糖，說成了一道茶點。」\n「這個臺階鋪得好，我就不客氣地下了。」"},{"id":"s6","portrait":"lingshou","who":"lingshou","text":"牠從條凳上跳下來，披風在門檻上掃了一下。\n「鏟屎的。下回帶現成的來，別給她碰鍋的機會。」\n牠頭也不回地往廊下去了。"},{"id":"s7","bg":"qianting","place":"前廳・黃昏","portrait":"daoshi_f","text":"黃昏，前廳的茶已經涼透。\n她用油紙包了幾顆供過的金桔，又添了兩顆山楂，紙角摺得整整齊齊。"},{"who":"daoshi_f","text":"「供過神明的，不算收禮，也不算送禮。施主帶回去，是把福分領走。」\n她把紙包放在案上推過來，沒有直接遞到你手裡。\n「山楂是添頭。嫌苦，就配濃茶。」"},{"me":true,"text":"「下回再來，我還帶甜的。」"},{"who":"daoshi_f","text":"「幾知觀不收外客之禮。」\n她答得很快，端起那盞涼掉的茶喝了一口，才慢慢補上後半句。\n「……不過神明那邊，我不好替祂推辭。」\n她送你到門邊，停在門檻內半步。\n「施主慢走。」","end":true}]$sc$::jsonb, null, '{}'::jsonb, 10, null, '糖大小姐', '她記得那位頭一回登門的施主臨走時說過：下回再來，還帶甜的。', true)
on conflict (id) do update set character_id = excluded.character_id, chapter = excluded.chapter, seq = excluded.seq,
  title = excluded.title, summary = excluded.summary, require_favor = excluded.require_favor,
  require_cultivation = excluded.require_cultivation, require_event = excluded.require_event,
  scenes = excluded.scenes, choices = null, rewards = excluded.rewards, reward_lingshi = excluded.reward_lingshi,
  reward_avatar = excluded.reward_avatar, reward_title = excluded.reward_title, reward_memory = excluded.reward_memory,
  published = excluded.published;

update character_titles set voice_hint = '說話比平日更甜、愛拿糖和點心打比方，守規矩但句句替自己留後門。', description = '規矩記得比誰都熟，後門也留得比誰都巧。'
 where unlock_event = 'daoshi_f_c1';
